JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE e.model_id = vm.id AND e.code = v.code AND e.year_from IS NULL AND e.year_to IS NULL
  AND EXISTS (SELECT 1 FROM generations g WHERE g.model_id = vm.id
              AND g.year_start <= v.year_to AND COALESCE(g.year_end, 9999) >= v.year_from);

-- C: years the market contradicts
UPDATE engines e
SET year_from = v.new_from, year_to = v.new_to, listings_seen = COALESCE(v.listings_seen, e.listings_seen),
    source = CASE WHEN length(COALESCE(e.source, '') || '; anos: ' || v.why) <= 200
                  THEN COALESCE(e.source || '; ', '') || 'anos: ' || v.why
                  ELSE left(COALESCE(e.source, ''), 200 - length('; anos: ' || v.why)) || '; anos: ' || v.why END
