) AS v(brand, model, code, old_from, old_to, new_from, new_to, listings_seen, why)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE e.model_id = vm.id AND e.code = v.code
  AND e.year_from = v.old_from AND e.year_to IS NOT DISTINCT FROM v.old_to
  AND EXISTS (SELECT 1 FROM generations g WHERE g.model_id = vm.id
              AND g.year_start <= v.new_to AND COALESCE(g.year_end, 9999) >= v.new_from);

-- D: names the matcher could not read
UPDATE engines e
SET code = v.new_code,
    source = left(COALESCE(e.source || '; ', '') || 'nome: ' || v.why, 200)
FROM (VALUES
    ('Fiat', '124 Spider', '1.4 T 140cv', '1.4 MultiAir Turbo 140cv', 'Standvirtual 2026-11-14: os 8 anúncios dizem MultiAir'),
    ('Abarth', '124 Spider', '1.4 T 170cv', '1.4 MultiAir Turbo 170cv', 'Standvirtual 2026-11-14: os 3 anúncios dizem MultiAir')
) AS v(brand, model, old_code, new_code, why)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE e.model_id = vm.id AND e.code = v.old_code
  AND NOT EXISTS (SELECT 1 FROM engines x WHERE x.model_id = vm.id AND x.code = v.new_code);

-- ...and when v67 is run again on a database built from the seeds
-- (load_seed --twice), it adds the old name back: that copy goes, if nothing
-- refers to it.
DELETE FROM engines e
USING (VALUES ('Fiat', '124 Spider', '1.4 T 140cv', '1.4 MultiAir Turbo 140cv'),
              ('Abarth', '124 Spider', '1.4 T 170cv', '1.4 MultiAir Turbo 170cv')) AS v(brand, model, old_code, new_code),
      brands b, vehicle_models vm
WHERE b.name = v.brand AND vm.brand_id = b.id AND vm.name = v.model
  AND e.model_id = vm.id AND e.code = v.old_code
  AND EXISTS (SELECT 1 FROM engines x WHERE x.model_id = vm.id AND x.code = v.new_code)
  AND NOT EXISTS (SELECT 1 FROM engine_issues r WHERE r.engine_id = e.id)
  AND NOT EXISTS (SELECT 1 FROM market_price_stats r WHERE r.engine_id = e.id)
  AND NOT EXISTS (SELECT 1 FROM market_price_stats_history r WHERE r.engine_id = e.id)
  AND NOT EXISTS (SELECT 1 FROM import_cost_estimates r WHERE r.engine_id = e.id)
  AND NOT EXISTS (SELECT 1 FROM reliability_evidence r WHERE r.engine_id = e.id)
  AND NOT EXISTS (SELECT 1 FROM reliability_scores_history r WHERE r.engine_id = e.id);

