    ('Volkswagen', 'Tiguan', '2.0 TDI 140cv', 'diesel', 1968::int, 140, 'manual', 7.2::numeric, 480, 2007, 2011, FALSE, 'Standvirtual 2026-11-14: 3 anúncios (Tiguan I, 2007–2011); consumo: sem dados; manutenção: estimativa da marca', 3, 'marca: 6 estudos publicados; motor sem desvio editorial'),
    ('Volkswagen', 'Tiguan', '1.4 TSI 150cv', 'gasolina', 1390::int, 150, 'manual', 7.2::numeric, 470, 2008, 2009, FALSE, 'Standvirtual 2026-11-14: 6 anúncios (Tiguan I, 2008–2009); consumo: sem dados; manutenção: estimativa da marca', 6, 'marca: 6 estudos publicados; motor sem desvio editorial'),
    ('Volkswagen', 'Tiguan', '2.0 TDI 110cv', 'diesel', 1968::int, 110, 'manual', 7.2::numeric, 450, 2011, 2015, FALSE, 'Standvirtual 2026-11-14: 8 anúncios (Tiguan I, 2011–2015); consumo: sem dados; manutenção: estimativa da marca', 8, 'marca: 6 estudos publicados; motor sem desvio editorial')
) AS v(brand, model, code, fuel_type, displacement_cc, power_hp, transmission,
       reliability_score, maintenance_cost_year, year_from, year_to, plug_in, source, listings_seen,
       reliability_basis)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE NOT EXISTS (SELECT 1 FROM engines e WHERE e.model_id = vm.id AND e.code = v.code)
  AND EXISTS (SELECT 1 FROM generations g WHERE g.model_id = vm.id
              AND g.year_start <= v.year_to AND COALESCE(g.year_end, 9999) >= v.year_from);

COMMIT;

-- Verify: engines still without years, and engines outside their model's generations.
SELECT 'no years' AS problem, b.name AS brand, vm.name AS model, e.code
FROM engines e JOIN vehicle_models vm ON vm.id = e.model_id JOIN brands b ON b.id = vm.brand_id
WHERE e.year_from IS NULL
UNION ALL
SELECT 'outside generations', b.name, vm.name, e.code
FROM engines e JOIN vehicle_models vm ON vm.id = e.model_id JOIN brands b ON b.id = vm.brand_id
WHERE e.year_from IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM generations g WHERE g.model_id = e.model_id
      AND g.year_start <= e.year_to AND COALESCE(g.year_end, 9999) >= e.year_from)
ORDER BY 1, 2, 3, 4;
